sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?director ?deathPlace WHERE {
  dbr:Yamata dbp:director ?director .
  OPTIONAL { ?director dbp:deathPlace ?deathPlace1 . }
  OPTIONAL { ?director dbo:deathPlace ?deathPlace2 . }
  BIND (COALESCE(?deathPlace1, ?deathPlace2) AS ?deathPlace)
}
LIMIT 100

